import {it,expect} from 'vitest'
import {fixture} from './fixture'
import {SceneGraph} from './graph'
class Param{value=1;calls:any[]=[];setValueAtTime(v:number,t:number){this.calls.push(['set',v,t])}linearRampToValueAtTime(v:number,t:number){this.calls.push(['ramp',v,t])}cancelScheduledValues(t:number){this.calls.push(['cancel',t])}cancelAndHoldAtTime(t:number){this.calls.push(['hold',t])}}
class Node{gain=new Param();buffer:any;loop=false;loopStart=0;loopEnd=0;starts:any[]=[];stops:any[]=[];connect(){}disconnect(){}start(...a:any[]){this.starts.push(a)}stop(...a:any[]){this.stops.push(a)}}
const setup=()=>{const nodes:Node[]=[],ctx:any={currentTime:10,createGain(){const n=new Node();nodes.push(n);return n},createBufferSource(){const n=new Node();nodes.push(n);return n}},p=fixture(),buffer:any={duration:80},pcm:any={aMaster:buffer,bMaster:buffer,a:{drums:buffer,bass:buffer,other:buffer},b:{master:buffer,drums:buffer,bass:buffer,other:buffer,vocals:buffer}};return{ctx,p,pcm,nodes}}
it('schedules lead, loops and continuous layers from one audio clock',()=>{const{ctx,p,pcm,nodes}=setup();const g=new SceneGraph(ctx,new Node() as any,p,pcm,'long',20,()=>{});expect(nodes.filter(n=>n.loop)).toHaveLength(3);expect(nodes.filter(n=>n.loop).every(n=>n.starts[0][0]===28)).toBe(true);expect(g.exit.at).toBe(40);expect(g.end).toBe(84)})
it('exits at nearest future approved boundary and maps native B position',()=>{const{ctx,p,pcm}=setup();const g=new SceneGraph(ctx,new Node() as any,p,pcm,'long',20,()=>{});ctx.currentTime=34;expect(g.requestExit()?.at).toBe(20);expect(g.end).toBe(64);expect(g.requestExit()?.at).toBe(20)})
it('cannot schedule a past exit and does not advance when audio context is paused',()=>{const{ctx,p,pcm}=setup();const g=new SceneGraph(ctx,new Node() as any,p,pcm,'long',20,()=>{});ctx.currentTime=28+18;expect(g.requestExit()?.at).toBe(30);const now=g.position;expect(g.position).toBe(now);ctx.currentTime+=2;expect(g.position).toBe(now+2)})
it('stops all loop and continuous sources on cancellation',()=>{const{ctx,p,pcm,nodes}=setup();const g=new SceneGraph(ctx,new Node() as any,p,pcm,'long',20,()=>{});g.stop();expect(nodes.filter(n=>n.starts.length).every(n=>n.stops.length>0)).toBe(true)})
it('ordinary reference uses masters, with no isolated source loops',()=>{const{ctx,p,pcm,nodes}=setup();const g=new SceneGraph(ctx,new Node() as any,p,pcm,'reference',20,()=>{});expect(nodes.some(n=>n.loop)).toBe(false);expect(g.variant).toBe('reference')})
it('cleans earlier scheduled sources if a later source fails during construction',()=>{const{ctx,p,pcm,nodes}=setup();const create=ctx.createBufferSource;let count=0;ctx.createBufferSource=()=>{const n=create();if(++count===3)n.start=()=>{throw Error('node failure')};return n};expect(()=>new SceneGraph(ctx,new Node() as any,p,pcm,'long',20,()=>{})).toThrow('node failure');expect(nodes.filter(n=>n.starts.length).every(n=>n.stops.length>0)).toBe(true)})
